mapper.update:
merge into T_CD15_BIG_ROLL a USING (
select #{BigRoll.bigRollCode,jdbcType=VARCHAR} BIG_ROLL_CODE, #{BigRoll.clothLength,jdbcType=DOUBLE} CLOTH_LENGTH, #{BigRoll.convertProduceNum,jdbcType=DOUBLE} CONVERT_PRODUCE_NUM, #{BigRoll.actClothLength,jdbcType=DOUBLE} ACT_CLOTH_LENGTH, #{BigRoll.createBy,jdbcType=VARCHAR} create_by, #{BigRoll.createTime,jdbcType=DATE} create_time, #{BigRoll.updateBy,jdbcType=VARCHAR} update_by, #{BigRoll.updateTime,jdbcType=DATE} update_time, #{BigRoll.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.BIG_ROLL_CODE = b.BIG_ROLL_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.CLOTH_LENGTH = b.CLOTH_LENGTH, a.CONVERT_PRODUCE_NUM = b.CONVERT_PRODUCE_NUM, a.ACT_CLOTH_LENGTH = b.ACT_CLOTH_LENGTH, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.BIG_ROLL_CODE , a.CLOTH_LENGTH , a.CONVERT_PRODUCE_NUM , a.ACT_CLOTH_LENGTH , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.BIG_ROLL_CODE , b.CLOTH_LENGTH , b.CONVERT_PRODUCE_NUM , b.ACT_CLOTH_LENGTH , b.create_by, sysdate, b.remark, '0' )
